import {batchRigidMeshes} from './BatchRigidMeshes.js';
import * as THREE from '../three.module.js';
export class StadiumEnvironmentController {
 constructor(scene){this.scene=scene;const architecture=new THREE.Group();scene.add(architecture);const m=c=>new THREE.MeshStandardMaterial({color:c,roughness:.8}),stone=m('#a5aaa4'),glass=m('#243d47'),roof=m('#e1dfcb');const boxes=[];const box=(w,h,d,mat,x,y,z)=>{const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);o.position.set(x,y,z);o.receiveShadow=true;architecture.add(o);boxes.push(o);return o;};box(26,7,8,stone,26,5,-62);box(28,.5,10,roof,26,9,-62);for(let i=0;i<10;i++)box(1.6,2,.08,glass,15+i*2.4,6.7,-57.9);for(let i=0;i<8;i++)box(7,.28,1,stone,9,1+i*.35,-55-i);for(let i=0;i<12;i++){const a=i/12*Math.PI*2;const b=box(8,.85,.15,glass,Math.sin(a)*65,.6,Math.cos(a)*65-10);b.rotation.y=a;}
 batchRigidMeshes(architecture);try{this.canvas=document.createElement('canvas');this.canvas.width=1024;this.canvas.height=512;this.ctx=this.canvas.getContext('2d');this.texture=new THREE.CanvasTexture(this.canvas);this.texture.colorSpace=THREE.SRGBColorSpace;const screen=new THREE.Mesh(new THREE.PlaneGeometry(12,6),new THREE.MeshBasicMaterial({map:this.texture}));screen.position.set(-23,8,-60);scene.add(screen);this.update('WELCOME TO CREASE','INTERNATIONAL OVAL');}catch{} }
 update(title,detail){if(!this.ctx||this.last===title+detail)return;this.last=title+detail;const c=this.ctx;c.fillStyle='#0c242c';c.fillRect(0,0,1024,512);c.fillStyle='#d8f58e';c.font='bold 70px Arial';c.fillText('CREASE',50,100);c.fillStyle='#f1f1df';c.font='bold 64px Arial';c.fillText(title,50,245,920);c.font='38px Arial';c.fillText(detail,50,365,920);this.texture.needsUpdate=true;}
}
